#!/usr/bin/env node
// Adds one row per generated SFX file to art/PROVENANCE.csv (D-063, proposed). Reads ready/manifest.json (written by
// prepare-sfx.js) and appends a row for each file that has none yet. The licence check is the owner's: the tool refuses
// to write unless the plan tier is named and --commercial-ok is given (the owner has confirmed that tier allows
// commercial use in the shipped game).
//   node prototype/tools/sfx-provenance.js --tool="<AI tool>" --plan="<plan tier>" --commercial-ok [--model="<version>"] [--date=YYYY-MM-DD] [--dry-run]
//   tests only: --csv=FILE --manifest=FILE
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', '..');
const DEFAULT_CSV = path.join(ROOT, 'art', 'PROVENANCE.csv');
const DEFAULT_MANIFEST = path.join(ROOT, 'prototype', 'audio', 'sfx-gen', 'ready', 'manifest.json');
const ASSET_DIR = 'prototype/audio/sfx-gen/ready/';

const field = v => '"' + String(v).replace(/"/g, '""') + '"';        // every field quoted, as in the existing rows

// Rows for every file in the manifest that the CSV does not list yet. Returns { rows, skipped }.
function rowsFor(manifest, csvText, o) {
  // First field of every line (quoted fields may hold commas).
  const have = new Set(csvText.split(/\r?\n/).map(l => { const m = /^"((?:[^"]|"")*)"/.exec(l); return m ? m[1].replace(/""/g, '"') : l.split(',')[0]; }));
  const rows = [], skipped = [];
  const list = [];
  for (const [id, entries] of Object.entries(manifest.cues || {})) for (const e of entries) list.push({ id, take: e.variant + 1, e });
  for (const [g, e] of Object.entries(manifest.beds || {})) list.push({ id: 'amb_' + g, take: 1, e });
  for (const { id, take, e } of list.sort((a, b) => (a.id + a.take < b.id + b.take ? -1 : 1))) {
    const asset = ASSET_DIR + e.file;
    if (have.has(asset)) { skipped.push(asset); continue; }
    rows.push([asset, o.tool, o.model, `brief-v1/${id}/take${take}`, o.date,
      `Generated by the owner with ${o.tool} (plan: ${o.plan}; owner confirmed commercial use). Source file: ${e.source || 'not recorded'}.`,
      'Take chosen by the owner. Trimmed, faded, leveled and encoded by prototype/tools/prepare-sfx.js. Not edited further.']);
  }
  return { rows, skipped };
}

function parseArgs(argv) {
  const o = { dryRun: false, commercialOk: false, model: 'not recorded', csv: DEFAULT_CSV, manifest: DEFAULT_MANIFEST,
    date: new Date().toISOString().slice(0, 10) };
  for (const a of argv) {
    let m;
    if (a === '--dry-run') o.dryRun = true;
    else if (a === '--commercial-ok') o.commercialOk = true;
    else if ((m = /^--tool=(.+)$/.exec(a))) o.tool = m[1];
    else if ((m = /^--plan=(.+)$/.exec(a))) o.plan = m[1];
    else if ((m = /^--model=(.+)$/.exec(a))) o.model = m[1];
    else if ((m = /^--date=(\d{4}-\d{2}-\d{2})$/.exec(a))) o.date = m[1];
    else if ((m = /^--csv=(.+)$/.exec(a))) o.csv = m[1];
    else if ((m = /^--manifest=(.+)$/.exec(a))) o.manifest = m[1];
    else if (a === '--help' || a === '-h') o.help = true;
    else throw new Error('unknown option ' + a);
  }
  return o;
}

function main(argv) {
  let o;
  try { o = parseArgs(argv); } catch (e) { console.error(e.message); return 1; }
  if (o.help) { console.log('Usage: node prototype/tools/sfx-provenance.js --tool="<AI tool>" --plan="<plan tier>" --commercial-ok [--model=..] [--date=YYYY-MM-DD] [--dry-run]'); return 0; }
  if (!o.tool || !o.plan || !o.commercialOk) {
    console.error('Refused: name the tool (--tool), the plan tier you checked (--plan) and confirm that tier allows commercial use (--commercial-ok).');
    return 1;
  }
  if (!fs.existsSync(o.manifest)) { console.error(`No manifest at ${o.manifest}: run prepare-sfx.js first.`); return 1; }
  const manifest = JSON.parse(fs.readFileSync(o.manifest, 'utf8'));
  const csvText = fs.existsSync(o.csv) ? fs.readFileSync(o.csv, 'utf8') : 'asset,tool,model_version,prompt_id,date,license_notes,human_edits\n';
  const { rows, skipped } = rowsFor(manifest, csvText, o);
  const lines = rows.map(r => r.map(field).join(','));
  if (o.dryRun) lines.forEach(l => console.log(l));
  else if (lines.length) {
    const sep = csvText.endsWith('\n') ? '' : '\n';
    fs.writeFileSync(o.csv, csvText + sep + lines.join('\n') + '\n');
  }
  console.log(`sfx-provenance: ${rows.length} row(s) ${o.dryRun ? 'would be added' : 'added'}, ${skipped.length} already listed`);
  return 0;
}

module.exports = { rowsFor, field };
if (require.main === module) process.exitCode = main(process.argv.slice(2));
